// DOCTOR JOBS WITH PROFILE SHARE APPLY — v19 Bridge
// ═══════════════════════════════════════════════════════════════════════
function DocJobsWithApply({profile}) {
  const [applyJob, setApplyJob] = useState(null);
  const [view, setView] = useState("list");

  if(view==="myapps") return <MyApplicationsView profile={profile} onBack={()=>setView("list")}/>;

  return (
    <div>
      {applyJob && (
        <ProfileShareModal
          profile={profile}
          job={applyJob}
          onClose={()=>setApplyJob(null)}
          onSubmit={()=>setApplyJob(null)}
        />
      )}
      {/* Header with My Applications link */}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
        <div>
          <div style={{color:"#fff",fontWeight:800,fontSize:15}}>💼 Job Opportunities</div>
          <div style={{color:"rgba(255,255,255,0.35)",fontSize:10}}>AI-matched · Share profile directly to admin</div>
        </div>
        <button onClick={()=>setView("myapps")} style={{background:"rgba(0,102,204,0.12)",border:"1px solid rgba(0,102,204,0.3)",borderRadius:9,padding:"6px 11px",color:"#42A5F5",fontSize:10,fontWeight:700,cursor:"pointer"}}>📋 My Applications</button>
      </div>
      {/* Info Banner */}
      <div style={{background:"linear-gradient(135deg,#0A1628,#1A3060)",border:"1px solid rgba(0,102,204,0.2)",borderRadius:13,padding:"10px 13px",marginBottom:13,display:"flex",gap:10,alignItems:"center"}}>
        <span style={{fontSize:20,flexShrink:0}}>🤝</span>
        <div style={{fontSize:10,color:"rgba(255,255,255,0.5)",lineHeight:1.6}}>Click <strong style={{color:"#42A5F5"}}>"Apply — Share Profile"</strong> on any job to securely share your STETHOSCO-verified profile with Admin for processing. Admin reviews and forwards to employer on your behalf.</div>
      </div>
      {/* Jobs list */}
      {JOBS_DB_NEW.map((job,i) => (
        <div key={job.id} style={{background:"rgba(255,255,255,0.02)",border:`1.5px solid ${job.color}22`,borderRadius:16,padding:13,marginBottom:10,animation:`su .3s ease ${i*.04}s both`}}>
          <div style={{display:"flex",gap:10,alignItems:"flex-start",marginBottom:9}}>
            <div style={{width:44,height:44,borderRadius:13,flexShrink:0,background:`${job.color}18`,border:`1.5px solid ${job.color}30`,display:"flex",alignItems:"center",justifyContent:"center",fontSize:22}}>🏥</div>
            <div style={{flex:1}}>
              <div style={{color:"#fff",fontWeight:800,fontSize:13}}>{job.title}</div>
              <div style={{color:"rgba(255,255,255,0.45)",fontSize:10,marginTop:1}}>{job.employer} · {job.city}, {job.state}</div>
              <div style={{color:"#00C9A7",fontWeight:800,fontSize:12,marginTop:2}}>₹{job.ctcMin}–{job.ctcMax} LPA</div>
            </div>
            <div style={{background:job.matchScore>=85?"rgba(0,201,167,0.12)":"rgba(244,160,18,0.12)",border:`1px solid ${job.matchScore>=85?"rgba(0,201,167,0.3)":"rgba(244,160,18,0.3)"}`,borderRadius:9,padding:"4px 9px",flexShrink:0,textAlign:"center"}}>
              <div style={{color:job.matchScore>=85?"#00C9A7":"#F4A012",fontWeight:900,fontSize:13}}>{job.matchScore||"—"}</div>
              <div style={{color:"rgba(255,255,255,0.35)",fontSize:7}}>MATCH%</div>
            </div>
          </div>
          <div style={{display:"flex",flexWrap:"wrap",gap:3,marginBottom:9}}>
            <span style={{background:"rgba(255,255,255,0.06)",borderRadius:5,padding:"2px 7px",color:"rgba(255,255,255,0.45)",fontSize:9}}>{job.jobType}</span>
            <span style={{background:"rgba(255,255,255,0.06)",borderRadius:5,padding:"2px 7px",color:"rgba(255,255,255,0.45)",fontSize:9}}>📅 {job.deadline}</span>
            <span style={{background:"rgba(255,255,255,0.06)",borderRadius:5,padding:"2px 7px",color:"rgba(255,255,255,0.45)",fontSize:9}}>👥 {job.applicants} applied</span>
            <span style={{background:"rgba(255,255,255,0.06)",borderRadius:5,padding:"2px 7px",color:"rgba(255,255,255,0.45)",fontSize:9}}>🎯 {job.openings} opening{job.openings!==1?"s":""}</span>
          </div>
          {job.benefits?.length>0&&(
            <div style={{display:"flex",flexWrap:"wrap",gap:2,marginBottom:9}}>
              {job.benefits.slice(0,3).map(b=><span key={b} style={{background:"rgba(0,201,167,0.08)",border:"1px solid rgba(0,201,167,0.15)",borderRadius:5,padding:"2px 6px",color:"#00C9A7",fontSize:8,fontWeight:600}}>{b}</span>)}
              {job.benefits.length>3&&<span style={{color:"rgba(255,255,255,0.25)",fontSize:8,padding:"2px 5px"}}>+{job.benefits.length-3} more</span>}
            </div>
          )}
          <button
            onClick={()=>setApplyJob(job)}
            style={{width:"100%",padding:"9px",background:`linear-gradient(135deg,${job.color},${job.color}CC)`,border:"none",borderRadius:10,color:"#fff",fontSize:11,fontWeight:800,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6}}
          >
            <span>📤</span> Apply — Share My Profile
          </button>
        </div>
      ))}
    </div>
  );
}



// ═══════════════════════════════════════════════════════════════════════
// PROFILE SHARE FOR JOB APPLICATIONS — v19
// Doctors & Medical Professionals share profile → Admin processes → Forwarded
// ═══════════════════════════════════════════════════════════════════════

let PROFILE_APPLICATIONS_DB = [];

function ProfileShareModal({profile, job, onClose, onSubmit}) {
  const [step, setStep] = useState(0);
  const [consent, setConsent] = useState({fullProfile:true, qualifications:true, experience:true, publications:false, ratings:false, contact:true});
  const [coverLetter, setCoverLetter] = useState("Dear Hiring Committee,\n\nI am submitting my profile for the above position. My qualifications and experience align well with your requirements. My complete STETHOSCO-verified profile is shared herewith for your review.\n\nI am available for interview at your convenience.\n\nSincerely,\n" + (profile?.name || "Applicant"));
  const [prefs, setPrefs] = useState({expectedCTC: profile?.expectedCTC || "", notice: profile?.notice || 30, relocate: profile?.relocate || true, message: ""});
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const refId = "SAPP-" + Date.now().toString().slice(-6);

  if (done) return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.9)",zIndex:500,display:"flex",alignItems:"center",justifyContent:"center",padding:16}}>
      <div style={{background:"linear-gradient(135deg,#050D1A,#0A1A30)",border:"1px solid rgba(0,201,167,0.3)",borderRadius:22,padding:28,textAlign:"center",width:"100%",maxWidth:370}}>
        <div style={{fontSize:60,marginBottom:14}}>🎉</div>
        <div style={{color:"#00C9A7",fontFamily:"Playfair Display,serif",fontSize:20,fontWeight:900,marginBottom:8}}>Application Submitted!</div>
        <div style={{color:"rgba(255,255,255,0.6)",fontSize:12,lineHeight:1.8,marginBottom:16}}>Your profile has been securely shared with the admin team. They will review and forward to the employer within 24–48 hours.</div>
        <div style={{background:"rgba(0,201,167,0.08)",border:"1px solid rgba(0,201,167,0.2)",borderRadius:12,padding:"11px 14px",marginBottom:18}}>
          <div style={{color:"rgba(255,255,255,0.4)",fontSize:9,marginBottom:4}}>APPLICATION REFERENCE</div>
          <div style={{color:"#00C9A7",fontWeight:900,fontSize:20,letterSpacing:1}}>{refId}</div>
        </div>
        <button onClick={onClose} style={{width:"100%",padding:"11px",background:"linear-gradient(135deg,#00C9A7,#0066CC)",border:"none",borderRadius:11,color:"#fff",fontSize:13,fontWeight:800,cursor:"pointer"}}>✓ Done</button>
      </div>
    </div>
  );

  const STEPS = ["Consent & Share","Cover Letter","Preferences","Review & Submit"];
  const c = "#0066CC";
  const bg = "rgba(0,5,15,0.97)";

  const handleSubmit = () => {
    setSubmitting(true);
    setTimeout(() => {
      PROFILE_APPLICATIONS_DB.push({
        id: refId, jobId: job?.id, jobTitle: job?.title, employer: job?.employer,
        city: job?.city, profile: profile?.name, consent, coverLetter, prefs,
        status: "Submitted to Admin", date: new Date().toISOString().slice(0,10),
        adminStatus: "Pending Review"
      });
      setSubmitting(false);
      setDone(true);
    }, 1800);
  };

  return (
    <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.85)",zIndex:500,overflowY:"auto",display:"flex",alignItems:"flex-start",justifyContent:"center",padding:"12px 0"}}>
      <div style={{background:"linear-gradient(135deg,#050D1A,#0A1A30)",border:"1px solid rgba(0,102,204,0.25)",borderRadius:22,width:"100%",maxWidth:390,margin:"auto",overflow:"hidden"}}>
        {/* Header */}
        <div style={{background:"linear-gradient(135deg,#0A1628,#1A3060)",padding:"16px 16px 12px",borderBottom:"1px solid rgba(255,255,255,0.07)"}}>
          <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
            <button onClick={onClose} style={{background:"rgba(255,255,255,0.08)",border:"none",borderRadius:8,width:30,height:30,cursor:"pointer",color:"#fff",fontSize:14}}>←</button>
            <div>
              <div style={{color:"#fff",fontWeight:800,fontSize:13}}>📤 Apply — Share My Profile</div>
              <div style={{color:"rgba(255,255,255,0.4)",fontSize:10}}>{job?.title} · {job?.employer}</div>
            </div>
          </div>
          {/* Step bar */}
          <div style={{display:"flex",alignItems:"center"}}>
            {STEPS.map((s,i) => (
              <div key={i} style={{display:"flex",alignItems:"center",flex:1}}>
                <div style={{display:"flex",flexDirection:"column",alignItems:"center",flex:1}}>
                  <div style={{width:22,height:22,borderRadius:"50%",background:i<step?"#00C9A7":i===step?c:"rgba(255,255,255,0.08)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,color:"#fff",fontWeight:900}}>{i<step?"✓":i+1}</div>
                  <div style={{color:i===step?c:"rgba(255,255,255,0.3)",fontSize:7,marginTop:2,textAlign:"center"}}>{s}</div>
                </div>
                {i<STEPS.length-1 && <div style={{height:2,flex:.5,marginBottom:14,background:i<step?"#00C9A7":"rgba(255,255,255,0.07)"}}/>}
              </div>
            ))}
          </div>
        </div>
        <div style={{padding:"14px 15px 18px"}}>
          {/* Step 0: Consent */}
          {step===0 && (
            <div>
              <div style={{color:"rgba(255,255,255,0.5)",fontSize:10,marginBottom:11,lineHeight:1.6}}>Select which parts of your profile to share with the employer via STETHOSCO Admin:</div>
              {[
                ["fullProfile","✅ Full Professional Profile","Name, photo, contact details, registration number"],
                ["qualifications","🎓 Qualifications & Certifications","All degrees, specializations, board certifications"],
                ["experience","🏥 Work Experience","Hospital history, designations, departments"],
                ["publications","📄 Research & Publications","Papers, journals, H-index, citations"],
                ["ratings","⭐ Patient Ratings & Reviews","Average rating and review summary"],
                ["contact","📞 Contact Information","Phone, email, LinkedIn profile URL"],
              ].map(([key,label,desc]) => (
                <div key={key} onClick={()=>setConsent(p=>({...p,[key]:!p[key]}))} style={{display:"flex",alignItems:"center",gap:11,padding:"9px 11px",background:consent[key]?"rgba(0,102,204,0.07)":"rgba(255,255,255,0.02)",border:`1.5px solid ${consent[key]?"rgba(0,102,204,0.3)":"rgba(255,255,255,0.07)"}`,borderRadius:11,marginBottom:7,cursor:"pointer"}}>
                  <div style={{width:20,height:20,borderRadius:6,background:consent[key]?"#0066CC":"rgba(255,255,255,0.07)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{consent[key]&&<span style={{color:"#fff",fontSize:11,fontWeight:900}}>✓</span>}</div>
                  <div style={{flex:1}}><div style={{color:"#fff",fontWeight:700,fontSize:11}}>{label}</div><div style={{color:"rgba(255,255,255,0.35)",fontSize:9,marginTop:1}}>{desc}</div></div>
                </div>
              ))}
              <div style={{background:"rgba(0,102,204,0.06)",border:"1px solid rgba(0,102,204,0.15)",borderRadius:9,padding:"8px 11px",marginBottom:12,fontSize:9,color:"rgba(255,255,255,0.4)",lineHeight:1.6}}>🔒 Your profile is shared securely with STETHOSCO Admin only. Admin reviews and forwards to employer. Direct employer contact details not shared without your consent.</div>
              <button onClick={()=>setStep(1)} style={{width:"100%",padding:"11px",background:"linear-gradient(135deg,#0052A3,#0066CC)",border:"none",borderRadius:11,color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer"}}>Cover Letter →</button>
            </div>
          )}
          {/* Step 1: Cover Letter */}
          {step===1 && (
            <div>
              <div style={{color:"rgba(255,255,255,0.4)",fontSize:10,fontWeight:700,marginBottom:6}}>PERSONALISE YOUR COVER LETTER</div>
              <textarea value={coverLetter} onChange={e=>setCoverLetter(e.target.value)} rows={10} style={{width:"100%",background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:11,color:"rgba(255,255,255,0.85)",fontSize:11,padding:"10px 12px",fontFamily:"Outfit,sans-serif",resize:"none"}}/>
              <div style={{display:"flex",gap:8,marginTop:10}}>
                <button onClick={()=>setStep(0)} style={{flex:1,padding:"10px",background:"rgba(255,255,255,0.07)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"#fff",fontSize:12,cursor:"pointer"}}>← Back</button>
                <button onClick={()=>setStep(2)} style={{flex:2,padding:"10px",background:"linear-gradient(135deg,#0052A3,#0066CC)",border:"none",borderRadius:10,color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer"}}>Preferences →</button>
              </div>
            </div>
          )}
          {/* Step 2: Preferences */}
          {step===2 && (
            <div>
              <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:9,marginBottom:10}}>
                <div>
                  <div style={{color:"rgba(255,255,255,0.4)",fontSize:10,fontWeight:700,marginBottom:5}}>EXPECTED CTC (LPA)</div>
                  <input value={prefs.expectedCTC} onChange={e=>setPrefs(p=>({...p,expectedCTC:e.target.value}))} placeholder="e.g. 42" type="number" style={{width:"100%",background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"rgba(255,255,255,0.9)",fontSize:12,padding:"9px 11px"}}/>
                </div>
                <div>
                  <div style={{color:"rgba(255,255,255,0.4)",fontSize:10,fontWeight:700,marginBottom:5}}>NOTICE PERIOD</div>
                  <select value={prefs.notice} onChange={e=>setPrefs(p=>({...p,notice:e.target.value}))} style={{width:"100%",background:"#0A1628",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"rgba(255,255,255,0.9)",fontSize:12,padding:"9px 11px"}}>
                    {["Immediate","15 Days","30 Days","45 Days","60 Days","90 Days","Negotiable"].map(o=><option key={o}>{o}</option>)}
                  </select>
                </div>
              </div>
              <div onClick={()=>setPrefs(p=>({...p,relocate:!p.relocate}))} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 11px",background:prefs.relocate?"rgba(0,201,167,0.07)":"rgba(255,255,255,0.02)",border:`1.5px solid ${prefs.relocate?"rgba(0,201,167,0.3)":"rgba(255,255,255,0.07)"}`,borderRadius:11,marginBottom:10,cursor:"pointer"}}>
                <div style={{width:20,height:20,borderRadius:6,background:prefs.relocate?"#00C9A7":"rgba(255,255,255,0.07)",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>{prefs.relocate&&<span style={{color:"#fff",fontSize:11,fontWeight:900}}>✓</span>}</div>
                <div style={{flex:1}}><div style={{color:"#fff",fontWeight:700,fontSize:11}}>Open to Relocation</div><div style={{color:"rgba(255,255,255,0.35)",fontSize:9}}>Willing to relocate for the right opportunity</div></div>
              </div>
              <div style={{color:"rgba(255,255,255,0.4)",fontSize:10,fontWeight:700,marginBottom:5}}>SPECIAL MESSAGE TO ADMIN (Optional)</div>
              <textarea value={prefs.message} onChange={e=>setPrefs(p=>({...p,message:e.target.value}))} rows={3} placeholder="Any specific note for admin processing…" style={{width:"100%",background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"rgba(255,255,255,0.85)",fontSize:11,padding:"9px 11px",fontFamily:"Outfit,sans-serif",resize:"none",marginBottom:10}}/>
              <div style={{display:"flex",gap:8}}>
                <button onClick={()=>setStep(1)} style={{flex:1,padding:"10px",background:"rgba(255,255,255,0.07)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"#fff",fontSize:12,cursor:"pointer"}}>← Back</button>
                <button onClick={()=>setStep(3)} style={{flex:2,padding:"10px",background:"linear-gradient(135deg,#0052A3,#0066CC)",border:"none",borderRadius:10,color:"#fff",fontSize:12,fontWeight:700,cursor:"pointer"}}>Review →</button>
              </div>
            </div>
          )}
          {/* Step 3: Review */}
          {step===3 && (
            <div>
              <div style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.08)",borderRadius:13,padding:"12px 13px",marginBottom:11}}>
                <div style={{color:"rgba(255,255,255,0.35)",fontSize:9,fontWeight:700,letterSpacing:.8,marginBottom:9}}>APPLICATION SUMMARY</div>
                {[
                  ["Position", job?.title],
                  ["Employer", job?.employer + " · " + job?.city],
                  ["Applicant", profile?.name],
                  ["CTC Expected", prefs.expectedCTC ? `₹${prefs.expectedCTC} LPA` : "Not specified"],
                  ["Notice Period", prefs.notice],
                  ["Relocation", prefs.relocate ? "Open to relocation" : "No"],
                  ["Profile Sections", Object.entries(consent).filter(([k,v])=>v).map(([k])=>k).join(", ")]
                ].map(([k,v])=>v&&(
                  <div key={k} style={{display:"flex",gap:10,padding:"5px 0",borderBottom:"1px solid rgba(255,255,255,0.05)"}}>
                    <div style={{color:"rgba(255,255,255,0.35)",fontSize:10,width:90,flexShrink:0}}>{k}</div>
                    <div style={{color:"rgba(255,255,255,0.7)",fontSize:10,flex:1}}>{v}</div>
                  </div>
                ))}
              </div>
              <div style={{background:"rgba(244,160,18,0.06)",border:"1px solid rgba(244,160,18,0.15)",borderRadius:9,padding:"8px 11px",marginBottom:12,fontSize:9,color:"rgba(255,255,255,0.45)",lineHeight:1.6}}>⚠️ By submitting, you consent to STETHOSCO Admin securely processing and forwarding your profile to the specified employer on your behalf. This action cannot be undone.</div>
              <div style={{display:"flex",gap:8}}>
                <button onClick={()=>setStep(2)} style={{flex:1,padding:"10px",background:"rgba(255,255,255,0.07)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"#fff",fontSize:12,cursor:"pointer"}}>← Back</button>
                <button onClick={handleSubmit} disabled={submitting} style={{flex:2,padding:"10px",background:"linear-gradient(135deg,#00C9A7,#0066CC)",border:"none",borderRadius:10,color:"#fff",fontSize:12,fontWeight:800,cursor:submitting?"not-allowed":"pointer",opacity:submitting?.6:1}}>{submitting?"⏳ Submitting…":"🚀 Submit Application"}</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function MyApplicationsView({profile, onBack}) {
  const apps = PROFILE_APPLICATIONS_DB.filter(a => a.profile === profile?.name);
  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
        <button onClick={onBack} style={{background:"rgba(255,255,255,0.07)",border:"none",borderRadius:9,width:32,height:32,cursor:"pointer",color:"#fff",fontSize:14}}>←</button>
        <div style={{flex:1}}><div style={{color:"#fff",fontWeight:800,fontSize:14}}>📋 My Job Applications</div><div style={{color:"rgba(255,255,255,0.35)",fontSize:10}}>{apps.length} applications submitted</div></div>
      </div>
      {apps.length===0 ? (
        <div style={{textAlign:"center",padding:"48px 20px"}}>
          <div style={{fontSize:48,marginBottom:12}}>📋</div>
          <div style={{color:"rgba(255,255,255,0.5)",fontSize:13}}>No applications yet</div>
          <div style={{color:"rgba(255,255,255,0.3)",fontSize:11,marginTop:5}}>Apply to jobs using "Share My Profile" button</div>
        </div>
      ) : apps.map((a,i)=>(
        <div key={a.id} style={{background:"rgba(255,255,255,0.02)",border:"1px solid rgba(255,255,255,0.07)",borderRadius:14,padding:13,marginBottom:9}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8}}>
            <div style={{flex:1}}><div style={{color:"#fff",fontWeight:800,fontSize:13}}>{a.jobTitle}</div><div style={{color:"rgba(255,255,255,0.4)",fontSize:10,marginTop:1}}>{a.employer} · {a.city}</div></div>
            <div style={{background:a.adminStatus==="Pending Review"?"rgba(244,160,18,0.12)":"rgba(0,201,167,0.12)",border:`1px solid ${a.adminStatus==="Pending Review"?"rgba(244,160,18,0.3)":"rgba(0,201,167,0.3)"}`,borderRadius:7,padding:"3px 8px",flexShrink:0,marginLeft:8}}><div style={{color:a.adminStatus==="Pending Review"?"#F4A012":"#00C9A7",fontSize:9,fontWeight:800}}>{a.adminStatus}</div></div>
          </div>
          <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
            <span style={{background:"rgba(255,255,255,0.05)",borderRadius:6,padding:"2px 8px",color:"rgba(255,255,255,0.4)",fontSize:9}}>📅 {a.date}</span>
            <span style={{background:"rgba(255,255,255,0.05)",borderRadius:6,padding:"2px 8px",color:"rgba(255,255,255,0.4)",fontSize:9}}>🆔 {a.id}</span>
          </div>
        </div>
      ))}
    </div>
  );
}

// Admin view for applications
function AdminApplicationsView({onBack}) {
  const [filter, setFilter] = useState("all");
  const apps = filter==="all" ? PROFILE_APPLICATIONS_DB : PROFILE_APPLICATIONS_DB.filter(a=>a.adminStatus===filter);
  const forward = (id) => {
    const idx = PROFILE_APPLICATIONS_DB.findIndex(a=>a.id===id);
    if(idx>=0) PROFILE_APPLICATIONS_DB[idx].adminStatus = "Forwarded to Employer";
  };
  return (
    <div>
      <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:14}}>
        <button onClick={onBack} style={{background:"rgba(255,255,255,0.07)",border:"none",borderRadius:9,width:32,height:32,cursor:"pointer",color:"#fff",fontSize:14}}>←</button>
        <div style={{flex:1}}><div style={{color:"#fff",fontWeight:800,fontSize:14}}>🗂️ Job Applications Queue</div><div style={{color:"rgba(255,255,255,0.35)",fontSize:10}}>{PROFILE_APPLICATIONS_DB.length} total applications</div></div>
      </div>
      <div style={{display:"flex",gap:6,marginBottom:12,flexWrap:"wrap"}}>
        {["all","Pending Review","Forwarded to Employer"].map(f=>(
          <span key={f} onClick={()=>setFilter(f)} style={{padding:"5px 11px",borderRadius:50,cursor:"pointer",background:filter===f?"rgba(0,201,167,0.15)":"rgba(255,255,255,0.05)",border:`1px solid ${filter===f?"rgba(0,201,167,0.4)":"rgba(255,255,255,0.1)"}`,color:filter===f?"#00C9A7":"rgba(255,255,255,0.5)",fontSize:10,fontWeight:700}}>{f==="all"?"All":f}</span>
        ))}
      </div>
      {apps.length===0 ? (
        <div style={{textAlign:"center",padding:"40px 20px",color:"rgba(255,255,255,0.4)",fontSize:12}}>No applications yet.</div>
      ) : apps.map((a,i)=>(
        <div key={a.id} style={{background:"rgba(255,255,255,0.02)",border:"1px solid rgba(255,255,255,0.07)",borderRadius:14,padding:13,marginBottom:9}}>
          <div style={{display:"flex",justifyContent:"space-between",marginBottom:7}}>
            <div><div style={{color:"#fff",fontWeight:800,fontSize:12}}>{a.profile}</div><div style={{color:"rgba(255,255,255,0.4)",fontSize:10}}>{a.jobTitle} · {a.employer}</div></div>
            <div style={{background:a.adminStatus==="Pending Review"?"rgba(244,160,18,0.12)":"rgba(0,201,167,0.12)",border:`1px solid ${a.adminStatus==="Pending Review"?"rgba(244,160,18,0.3)":"rgba(0,201,167,0.3)"}`,borderRadius:7,padding:"3px 8px",flexShrink:0,height:"fit-content"}}><div style={{color:a.adminStatus==="Pending Review"?"#F4A012":"#00C9A7",fontSize:9,fontWeight:800}}>{a.adminStatus}</div></div>
          </div>
          <div style={{display:"flex",gap:6,marginBottom:8}}>
            <span style={{background:"rgba(255,255,255,0.05)",borderRadius:5,padding:"2px 7px",color:"rgba(255,255,255,0.4)",fontSize:9}}>📅 {a.date}</span>
            <span style={{background:"rgba(255,255,255,0.05)",borderRadius:5,padding:"2px 7px",color:"rgba(255,255,255,0.4)",fontSize:9}}>🆔 {a.id}</span>
          </div>
          {a.adminStatus==="Pending Review" && (
            <button onClick={()=>forward(a.id)} style={{width:"100%",padding:"8px",background:"linear-gradient(135deg,#00C9A7,#0066CC)",border:"none",borderRadius:9,color:"#fff",fontSize:11,fontWeight:700,cursor:"pointer"}}>📤 Forward to Employer</button>
          )}
        </div>
      ))}
    </div>
  );
}


