// STETHOSCO v23 — AI PROFILE MATCHING + EMPLOYER PORTAL + STUDENT INTERN
// ═══════════════════════════════════════════════════════════════════════

// ── AI Job Match Score Engine ──
// Weights: Qualifications 30%, Experience 25%, Specialty 20%, Package 15%, Location 10%
function computeMatchScore(profile, job) {
  let score = 0;
  const reasons = [];
  // Qualification match (30pts)
  const profQuals = [profile.qual, profile.pgQual, profile.course].filter(Boolean).map(q=>(q||"").toLowerCase());
  const jobQuals = (job.qualification||job.quals||[]).map(q=>(q||"").toLowerCase());
  const qualMatch = jobQuals.length===0 || jobQuals.some(jq => profQuals.some(pq => pq.includes(jq.split(" ")[0]) || jq.includes(pq.split(" ")[0])));
  if(qualMatch) { score += 30; reasons.push("Qualification ✓"); }
  else score += 8;
  // Experience match (25pts)
  const profExp = parseInt(profile.exp)||parseInt(profile.experience)||0;
  const jobExpStr = job.experience||job.expReq||"0";
  const [eMin,eMax] = jobExpStr.match(/\d+/g)||["0","99"];
  const expOk = profExp >= parseInt(eMin||0);
  if(expOk) { score += 25; reasons.push("Experience ✓"); }
  else score += 5;
  // Specialty/Role match (20pts)
  const profSpec = [(profile.specialty||""), (profile.role||""), (profile.interests||[]).join(" ")].join(" ").toLowerCase();
  const jobRole = [(job.role||job.title||""), (job.dept||""), (job.specialty||"")].join(" ").toLowerCase();
  const specWords = jobRole.split(/\s+/).filter(w=>w.length>3);
  const specMatches = specWords.filter(w => profSpec.includes(w)).length;
  const specScore = Math.min(20, Math.round((specMatches / Math.max(specWords.length,1)) * 20) + (specMatches>0?5:0));
  score += specScore;
  if(specScore>=10) reasons.push("Specialty ✓");
  // Package match (15pts) - higher = better match
  const profExpCTC = parseInt(profile.expectedCTC)||parseInt(profile.ctcExpected)||0;
  const jobMaxCTC = parseInt(job.ctcMax)||parseInt(job.salaryMax)||0;
  if(jobMaxCTC > 0 && profExpCTC > 0) {
    const packageRatio = jobMaxCTC / profExpCTC;
    if(packageRatio >= 1.1) { score += 15; reasons.push("Package exceeds expectation ✓"); }
    else if(packageRatio >= 0.95) { score += 12; reasons.push("Package matches ✓"); }
    else if(packageRatio >= 0.80) score += 6;
  } else score += 8; // unknown package, give partial
  // Location/relocation (10pts)
  const profCity = (profile.city||"").toLowerCase();
  const profState = (profile.state||"").toLowerCase();
  const jobCity = (job.hospitalCity||job.city||"").toLowerCase();
  const jobState = (job.hospitalState||job.state||"").toLowerCase();
  if(jobCity && profCity && jobCity === profCity) { score += 10; reasons.push("Same city ✓"); }
  else if(jobState && profState && jobState === profState) { score += 7; reasons.push("Same state ✓"); }
  else if(profile.relocate || profile.openToRelocation) { score += 5; reasons.push("Open to relocation ✓"); }
  else score += 2;
  return { score: Math.min(100, score), reasons };
}

