// 🩺 DOCTOR PORTAL
// ══════════════════════════════════════════
function DoctorPortal({tab,setTab}) {
  const [docProfile,setDocProfile]=useState({
    photo:"🧑‍⚕️",name:"Dr. Suresh Mehta",gender:"Male",dob:"1978-03-15",phone:"9876543210",email:"suresh.mehta@gmail.com",
    regNo:"MH-12345",regBody:"Maharashtra Medical Council",regYear:"2002",
    mbbs:{qual:"MBBS",college:"Seth GS Medical College Mumbai",year:"2002"},
    pg:{qual:"MD",college:"AIIMS New Delhi",year:"2005",specialty:"Cardiology"},
    dm:{qual:"DM",college:"AIIMS New Delhi",year:"2007",specialty:"DM Cardiology"},
    patientsTreated:4200,surgeries:340,
    hospitals:[{id:1,name:"Apollo Hospitals Mumbai",from:"2010",to:"2018",desig:"Senior Consultant"},{id:2,name:"Kokilaben Dhirubhai Ambani Hospital",from:"2018",to:"Present",desig:"HOD Cardiology"}],
    awards:[{id:1,title:"Best Cardiologist of the Year 2023",by:"IMA Maharashtra"},{id:2,title:"Excellence in Research Award 2021",by:"Cardiology Society of India"}],
    publications:[{id:1,title:"Novel approach to STEMI management in rural India",journal:"JAPI 2022"},{id:2,title:"Five-year outcomes of TAVI in elderly patients",journal:"IJCC 2021"}],
    currentCTC:28,expectedCTC:42,notice:60,relocate:true,relocateSalary:40,
    linkedin:"linkedin.com/in/suresh-mehta-cardio",scholar:"scholar.google.com/suresh-mehta",researchgate:"researchgate.net/profile/Suresh-Mehta",youtube:"youtube.com/@drsureshmehta",facebook:"facebook.com/drsureshmehta",instagram:"instagram.com/drsureshmehta",
    state:"Maharashtra",city:"Mumbai"
  });
  const [editing,setEditing]=useState(false);
  const [selState,setSelState]=useState("Maharashtra");
  const [selCity,setSelCity]=useState("Mumbai");

  if(tab==="verify") return <VerificationSubmit roleId="doctor" roleName="Doctor" onBack={()=>setTab("dashboard")}/>;
  if(tab==="profile") return <DoctorProfile prof={docProfile} setProf={setDocProfile} editing={editing} setEditing={setEditing} selState={selState} setSelState={setSelState} selCity={selCity} setSelCity={setSelCity}/>;
  if(tab==="schedule") return <DoctorSchedule/>;
  if(tab==="patients") return <DoctorPatients/>;
  if(tab==="aijobs") return <AIJobMatchBoard userProfile={{...docProfile, qual:docProfile.pg?.qual||docProfile.mbbs?.qual, exp:"15 years", specialty:docProfile.pg?.specialty||"Cardiology", expectedCTC:docProfile.expectedCTC+"L", role:docProfile.pg?.specialty||"Cardiologist", relocate:docProfile.relocate, city:docProfile.city, state:docProfile.state}} roleColor="#0066CC" onBack={()=>setTab("dashboard")}/>;
  if(tab==="availability") return <DoctorAvailabilityMgr onBack={()=>setTab("dashboard")}/>;
  if(tab==="earnings") return <DoctorEarningsDashboard onBack={()=>setTab("dashboard")}/>;
  if(tab==="emr") return <DoctorEMRPanel onBack={()=>setTab("dashboard")}/>;
  if(tab==="proalerts") return <ProJobAlertsSubscription onBack={()=>setTab("dashboard")} audienceLabel="Doctors" defaultPlan="hotjobs"/>;
  if(tab==="nearby") return <NearbyHospitalSearch roleColor="#0066CC" onBack={()=>setTab("dashboard")}/>;
  if(tab==="boost") return <BoostCenter vertical="doctor" onBack={()=>setTab("dashboard")}/>;
  return <DoctorDashboard setTab={setTab}/>;
}



