        {[{t:"09:00 AM",p:"Rajesh Kumar",type:"Video 📹",c:"HTN Follow-up",done:false},{t:"10:30 AM",p:"Priya Sharma",type:"Clinic 🏥",c:"Diabetes Review",done:false},{t:"12:00 PM",p:"Amit Patel",type:"Video 📹",c:"Post-Op Check",done:true}].map((a,i)=>(
          <div key={i} style={{display:"flex",gap:10,background:"rgba(255,255,255,0.04)",border:`1px solid rgba(0,201,167,${a.done?0.05:0.15})`,borderRadius:12,padding:"10px 12px",marginBottom:7,opacity:a.done?0.5:1}}>
            <div style={{width:38,height:38,borderRadius:10,background:"rgba(0,102,204,0.15)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:17,flexShrink:0}}>👤</div>
            <div style={{flex:1}}><div style={{color:"#fff",fontWeight:600,fontSize:13}}>{a.p}</div><div style={{color:"rgba(255,255,255,0.38)",fontSize:11}}>{a.c} · {a.type}</div></div>
            <div style={{textAlign:"right"}}><div style={{color:a.done?"rgba(255,255,255,0.28)":"#00C9A7",fontSize:11,fontWeight:700}}>{a.t}</div><div style={{color:a.done?"rgba(255,255,255,0.2)":"#4CAF50",fontSize:10,marginTop:2}}>{a.done?"✓ Done":"⏳ Upcoming"}</div></div>
          </div>
        ))}
