// 🔗 SHARE PROFILE BUTTON – Doctor
// ══════════════════════════════════════════
function ShareProfileBtn({name,spec,city,rating,reviews}) {
  const [showModal,setShowModal]=useState(false);
  const [copied,setCopied]=useState(false);
  const [activeShare,setActiveShare]=useState(null);
  const slug=(name||"doctor").toLowerCase().replace(/dr\.\s*/i,"").replace(/\s+/g,"-").replace(/[^a-z0-9-]/g,"");
  const profileUrl=`stethosco.app/dr/${slug}`;
  const copy=()=>{setCopied(true);setTimeout(()=>setCopied(false),2500);};
  const shareChannels=[
    {label:"WhatsApp",icon:"💬",bg:"#25D366",msg:"Share via WhatsApp"},
    {label:"Instagram",icon:"📸",bg:"#E1306C",msg:"Copy link for Instagram"},
    {label:"Facebook",icon:"📘",bg:"#1877F2",msg:"Share on Facebook"},
    {label:"Twitter",icon:"🐦",bg:"#1DA1F2",msg:"Post on Twitter"},
    {label:"LinkedIn",icon:"💼",bg:"#0A66C2",msg:"Share on LinkedIn"},
    {label:"Email",icon:"✉️",bg:"#0066CC",msg:"Share via Email"},
    {label:"SMS",icon:"💬",bg:"#5E35B1",msg:"Share via SMS"},
    {label:"QR Code",icon:"📷",bg:"#37474F",msg:"Download QR Code"},
  ];
  return (
    <>
      <Btn onClick={()=>setShowModal(true)} style={{background:"linear-gradient(135deg,#8B5CF6,#6D28D9)",padding:"10px 16px",letterSpacing:0.2}}>🔗 Share Profile</Btn>
      {showModal&&(
        <div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.92)",zIndex:700,display:"flex",alignItems:"flex-end"}} onClick={()=>setShowModal(false)}>
          <div onClick={e=>e.stopPropagation()} style={{background:"linear-gradient(170deg,#0B1624,#0F1E36)",borderRadius:"26px 26px 0 0",width:"100%",padding:"24px 20px 32px",maxHeight:"90vh",overflowY:"auto"}}>
            {/* Handle */}
            <div style={{width:38,height:4,background:"rgba(255,255,255,0.12)",borderRadius:2,margin:"0 auto 20px"}}/>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:18}}>
              <div>
                <div style={{color:"#fff",fontWeight:900,fontSize:18,letterSpacing:-0.3}}>Share Your STETHOSCO Profile</div>
                <div style={{color:"rgba(255,255,255,0.38)",fontSize:12,marginTop:2}}>Let patients discover you and book online</div>
              </div>
              <button onClick={()=>setShowModal(false)} style={{background:"rgba(255,255,255,0.06)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:11,width:36,height:36,color:"rgba(255,255,255,0.6)",cursor:"pointer",fontSize:18,display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>
            </div>

            {/* Profile card preview */}
            <div style={{background:"linear-gradient(135deg,#0D3A6E,#1565C0)",borderRadius:20,padding:16,marginBottom:16,position:"relative",overflow:"hidden"}}>
              <div style={{position:"absolute",top:-20,right:-20,width:80,height:80,borderRadius:"50%",background:"rgba(0,201,167,0.1)"}}/>
              <div style={{display:"flex",gap:13,alignItems:"center",position:"relative"}}>
                <div style={{width:56,height:56,borderRadius:16,background:"linear-gradient(135deg,#0D47A1,#00C9A7)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:28,boxShadow:"0 4px 16px rgba(0,0,0,0.3)"}}>👨‍⚕️</div>
                <div style={{flex:1}}>
                  <div style={{color:"#fff",fontWeight:900,fontSize:16,letterSpacing:-0.3}}>{name||"Dr. Suresh Mehta"}</div>
                  <div style={{color:"rgba(255,255,255,0.6)",fontSize:12,marginTop:2}}>{spec||"Cardiology"} · {city||"Mumbai"}</div>
                  <div style={{display:"flex",gap:8,marginTop:5,alignItems:"center"}}>
                    <div style={{color:"#00C9A7",fontSize:11,fontWeight:700}}>✓ STETHOSCO Verified</div>
                    {rating&&<div style={{color:"#F4A012",fontSize:11,fontWeight:700}}>⭐ {rating}</div>}
                    {reviews&&<div style={{color:"rgba(255,255,255,0.4)",fontSize:10}}>({reviews} reviews)</div>}
                  </div>
                </div>
              </div>
            </div>

            {/* Profile URL */}
            <div style={{background:"rgba(139,92,246,0.08)",border:"1px solid rgba(139,92,246,0.3)",borderRadius:14,padding:"13px 15px",marginBottom:14}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
                <div style={{color:"rgba(255,255,255,0.38)",fontSize:10,letterSpacing:1,fontWeight:700}}>🔗 YOUR STETHOSCO PROFILE LINK</div>
                <div onClick={copy} style={{background:copied?"rgba(76,175,80,0.2)":"rgba(139,92,246,0.2)",border:`1px solid ${copied?"rgba(76,175,80,0.4)":"rgba(139,92,246,0.4)"}`,borderRadius:7,padding:"3px 9px",cursor:"pointer",color:copied?"#81C784":"#A78BFA",fontSize:11,fontWeight:700}}>
                  {copied?"✓ Copied":"📋 Copy"}
                </div>
              </div>
              <div style={{fontFamily:"monospace",color:"#C4B5FD",fontSize:12,wordBreak:"break-all",letterSpacing:0.3}}>{profileUrl}</div>
            </div>

            {/* Share channels */}
            <div style={{color:"rgba(255,255,255,0.38)",fontSize:11,marginBottom:10,letterSpacing:0.5}}>SHARE VIA</div>
            <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:9,marginBottom:16}}>
              {shareChannels.map(s=>(
                <div key={s.label} onClick={()=>setActiveShare(s.label)} style={{background:activeShare===s.label?`${s.bg}30`:`${s.bg}14`,border:`1.5px solid ${activeShare===s.label?s.bg:`${s.bg}30`}`,borderRadius:14,padding:"12px 6px",textAlign:"center",cursor:"pointer",transition:"all .15s"}}>
                  <div style={{fontSize:22,marginBottom:5}}>{s.icon}</div>
                  <div style={{color:"rgba(255,255,255,0.55)",fontSize:9,fontWeight:600,lineHeight:1.2}}>{s.label}</div>
                </div>
              ))}
            </div>

            {activeShare&&(
              <div style={{background:"rgba(255,255,255,0.04)",border:"1px solid rgba(255,255,255,0.08)",borderRadius:12,padding:"11px 14px",marginBottom:14,display:"flex",alignItems:"center",gap:10}}>
                <div style={{fontSize:20}}>{shareChannels.find(s=>s.label===activeShare)?.icon}</div>
                <div style={{flex:1,color:"rgba(255,255,255,0.6)",fontSize:12}}>{shareChannels.find(s=>s.label===activeShare)?.msg}</div>
                <Btn style={{fontSize:11,padding:"6px 12px",background:"linear-gradient(135deg,#8B5CF6,#6D28D9)"}}>Open →</Btn>
              </div>
            )}

            <div style={{textAlign:"center",color:"rgba(255,255,255,0.2)",fontSize:11,lineHeight:1.6}}>
              Patients who open your link can view your full profile,<br/>ratings, social links, and book appointments online
            </div>
          </div>
        </div>
      )}
    </>
  );
}

