const ALL_SPECS = ["All Specialties","Cardiology","Neurology","Oncology","Orthopaedics","Gynaecology & Obs","Paediatrics","Dermatology","Ophthalmology","ENT","Gastroenterology","Nephrology","Urology","Pulmonology","Endocrinology","Psychiatry","Radiology","Pathology","Anaesthesia","Emergency Medicine","General Surgery","Plastic Surgery","Neonatology","Rheumatology","Haematology"];

function PatientSearch({setViewDoctor,setViewHospital}) {
  const [query,setQuery]=useState("");
  const [searchTab,setSearchTab]=useState("doctors");
  const [selSpec,setSelSpec]=useState("All Specialties");
  const [minRating,setMinRating]=useState(0);
  const [selState,setSelState]=useState("All States");
  const [onlineOnly,setOnlineOnly]=useState(false);
  const [showFilters,setShowFilters]=useState(false);
  const [selSlot,setSelSlot]=useState(null);
  const [bookingDoc,setBookingDoc]=useState(null);

  const states = ["All States",...[...new Set(SEARCH_DOCTORS.map(d=>d.state))].sort()];
  const hospStates = ["All States",...[...new Set(SEARCH_HOSPITALS.map(h=>h.state))].sort()];

  const filteredDocs = SEARCH_DOCTORS.filter(d=>{
    const q = query.toLowerCase();
    const matchQ = !query || d.name.toLowerCase().includes(q) || d.spec.toLowerCase().includes(q) || d.city.toLowerCase().includes(q) || d.subSpec.toLowerCase().includes(q);
    const matchSpec = selSpec==="All Specialties" || d.spec===selSpec;
    const matchRating = d.rating >= (minRating||0);
    const matchState = selState==="All States" || d.state===selState;
    const matchOnline = !onlineOnly || d.online;
    return matchQ && matchSpec && matchRating && matchState && matchOnline;
  });

  const filteredHosps = SEARCH_HOSPITALS.filter(h=>{
    const q = query.toLowerCase();
    const matchQ = !query || h.name.toLowerCase().includes(q) || h.city.toLowerCase().includes(q) || h.type.toLowerCase().includes(q) || h.specs.some(s=>s.toLowerCase().includes(q));
    const matchSpec = selSpec==="All Specialties" || h.specs.some(s=>s.toLowerCase().includes(selSpec.toLowerCase()));
    const matchRating = h.rating >= (minRating||0);
    const matchState = selState==="All States" || h.state===selState;
    return matchQ && matchSpec && matchRating && matchState;
  });

  const activeFilters = (selSpec!=="All Specialties"?1:0)+(minRating>0?1:0)+(selState!=="All States"?1:0)+(onlineOnly?1:0);
  const selSt = {width:"100%",background:"rgba(255,255,255,0.05)",border:"1.5px solid rgba(0,201,167,0.2)",borderRadius:10,color:"#fff",fontSize:12,padding:"9px 11px"};

  return (
    <div style={{display:"flex",flexDirection:"column",gap:12}}>
      {/* Header */}
      <div style={{background:"linear-gradient(135deg,#0D1F40,#0A2A50)",borderRadius:18,padding:16}}>
        <div style={{color:"#00C9A7",fontSize:11,fontWeight:700,letterSpacing:1,marginBottom:4}}>🔍 STETHOSCO SEARCH</div>
        <div style={{color:"#fff",fontWeight:800,fontSize:17,fontFamily:"Playfair Display,serif",lineHeight:1.2}}>Find the Right Doctor<br/>or Hospital</div>
        <div style={{color:"rgba(255,255,255,0.45)",fontSize:11,marginTop:5}}>{SEARCH_DOCTORS.length} doctors · {SEARCH_HOSPITALS.length} hospitals · Pan India</div>
      </div>

      {/* Search bar */}
      <div style={{display:"flex",gap:9}}>
        <div style={{flex:1,background:"rgba(255,255,255,0.06)",border:"1.5px solid rgba(0,201,167,0.25)",borderRadius:13,display:"flex",alignItems:"center",gap:10,padding:"11px 14px"}}>
          <span style={{fontSize:16,flexShrink:0}}>🔍</span>
          <input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Doctor name, speciality, city…" style={{background:"transparent",border:"none",color:"#fff",fontSize:12,flex:1,fontFamily:"Outfit"}}/>
          {query&&<span onClick={()=>setQuery("")} style={{color:"rgba(255,255,255,0.3)",cursor:"pointer",fontSize:16}}>×</span>}
        </div>
        <div onClick={()=>setShowFilters(!showFilters)} style={{position:"relative",background:showFilters||activeFilters>0?"rgba(0,201,167,0.15)":"rgba(255,255,255,0.05)",border:`1.5px solid ${showFilters||activeFilters>0?"rgba(0,201,167,0.4)":"rgba(255,255,255,0.1)"}`,borderRadius:13,width:44,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",flexShrink:0}}>
          <span style={{fontSize:18}}>⚙️</span>
          {activeFilters>0&&<div style={{position:"absolute",top:-5,right:-5,width:16,height:16,background:"#E91E63",borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,color:"#fff",fontWeight:800}}>{activeFilters}</div>}
        </div>
      </div>

      {/* Filters panel */}
      {showFilters&&(
        <div style={{background:"rgba(10,30,60,0.9)",border:"1px solid rgba(0,201,167,0.2)",borderRadius:15,padding:15,display:"flex",flexDirection:"column",gap:11}}>
          <div style={{color:"#00C9A7",fontSize:12,fontWeight:700}}>⚙️ Filters</div>
          <div>
            <div style={{color:"rgba(255,255,255,0.38)",fontSize:11,marginBottom:6}}>Speciality</div>
            <div style={{display:"flex",gap:6,flexWrap:"wrap"}}>
              {["All Specialties","Cardiology","Neurology","Oncology","Orthopaedics","Dermatology","Paediatrics","Psychiatry","Endocrinology","Gastroenterology","Gynaecology & Obs","Ophthalmology","Pulmonology","Nephrology"].map(s=>(
                <div key={s} onClick={()=>setSelSpec(s)} style={{background:selSpec===s?"rgba(0,201,167,0.2)":"rgba(255,255,255,0.04)",border:`1px solid ${selSpec===s?"rgba(0,201,167,0.5)":"rgba(255,255,255,0.08)"}`,borderRadius:8,padding:"5px 10px",cursor:"pointer",color:selSpec===s?"#00C9A7":"rgba(255,255,255,0.45)",fontSize:11,fontWeight:selSpec===s?700:400,whiteSpace:"nowrap"}}>{s}</div>
              ))}
            </div>
          </div>
          <div>
            <div style={{color:"rgba(255,255,255,0.38)",fontSize:11,marginBottom:6}}>Minimum Rating</div>
            <div style={{display:"flex",gap:7}}>
              {[[0,"Any"],[4.0,"4.0+"],[4.5,"4.5+"],[4.8,"4.8+"],[4.9,"4.9+"]].map(([v,l])=>(
                <div key={l} onClick={()=>setMinRating(v)} style={{background:minRating===v?"rgba(244,160,18,0.2)":"rgba(255,255,255,0.04)",border:`1px solid ${minRating===v?"rgba(244,160,18,0.5)":"rgba(255,255,255,0.08)"}`,borderRadius:8,padding:"5px 10px",cursor:"pointer",color:minRating===v?"#F4A012":"rgba(255,255,255,0.45)",fontSize:11,fontWeight:minRating===v?700:400}}>⭐ {l}</div>
              ))}
            </div>
          </div>
          <div>
            <div style={{color:"rgba(255,255,255,0.38)",fontSize:11,marginBottom:6}}>State</div>
            <select value={selState} onChange={e=>setSelState(e.target.value)} style={selSt}>
              {[...states,...hospStates.filter(s=>!states.includes(s))].map(s=><option key={s} value={s} style={{background:"#0A1A35"}}>{s}</option>)}
            </select>
          </div>
          {searchTab==="doctors"&&(
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",background:"rgba(255,255,255,0.04)",borderRadius:9,padding:"9px 12px"}}>
              <div style={{color:"rgba(255,255,255,0.6)",fontSize:12}}>📹 Online Consultation Only</div>
              <div onClick={()=>setOnlineOnly(!onlineOnly)} style={{width:38,height:21,borderRadius:11,background:onlineOnly?"#00C9A7":"rgba(255,255,255,0.1)",cursor:"pointer",position:"relative",transition:"background .25s"}}>
                <div style={{width:17,height:17,borderRadius:"50%",background:"#fff",position:"absolute",top:2,left:onlineOnly?19:2,transition:"left .25s"}}/>
              </div>
            </div>
          )}
          {activeFilters>0&&<div onClick={()=>{setSelSpec("All Specialties");setMinRating(0);setSelState("All States");setOnlineOnly(false);}} style={{color:"#FF4757",fontSize:11,fontWeight:700,textAlign:"center",cursor:"pointer",padding:"5px 0"}}>✕ Clear all filters</div>}
        </div>
      )}

      {/* Tabs */}
      <div style={{display:"flex",background:"rgba(255,255,255,0.04)",borderRadius:12,padding:3,gap:3}}>
        {[{id:"doctors",label:`🩺 Doctors (${filteredDocs.length})`},{id:"hospitals",label:`🏥 Hospitals (${filteredHosps.length})`}].map(t=>(
          <div key={t.id} onClick={()=>setSearchTab(t.id)} style={{flex:1,textAlign:"center",padding:"9px 4px",borderRadius:10,background:searchTab===t.id?"linear-gradient(135deg,#0066CC,#00897B)":"transparent",color:searchTab===t.id?"#fff":"rgba(255,255,255,0.4)",fontSize:11,fontWeight:searchTab===t.id?700:400,cursor:"pointer",transition:"all .2s"}}>{t.label}</div>
        ))}
      </div>

      {/* Results */}
      {searchTab==="doctors"&&(
        <>
          {filteredDocs.length===0&&<div style={{textAlign:"center",padding:"30px 0"}}><div style={{fontSize:40,marginBottom:10}}>🔍</div><div style={{color:"rgba(255,255,255,0.4)",fontSize:13}}>No doctors matched your search</div><div onClick={()=>{setSelSpec("All Specialties");setMinRating(0);setSelState("All States");setOnlineOnly(false);setQuery("");}} style={{color:"#00C9A7",fontSize:12,marginTop:8,cursor:"pointer",fontWeight:700}}>Clear filters</div></div>}
          {filteredDocs.map((d,i)=>(
            <div key={d.id} onClick={()=>setViewDoctor(d)} style={{background:"rgba(255,255,255,0.035)",border:"1px solid rgba(255,255,255,0.07)",borderRadius:16,padding:14,cursor:"pointer",transition:"border-color .2s"}}>
              <div style={{display:"flex",gap:11,alignItems:"flex-start"}}>
                <div style={{position:"relative",flexShrink:0}}>
                  <div style={{width:50,height:50,borderRadius:14,background:"linear-gradient(135deg,#0D47A1,#1565C0)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:26}}>{d.img}</div>
                  {d.verified&&<div style={{position:"absolute",bottom:-3,right:-3,width:16,height:16,background:"#4CAF50",borderRadius:"50%",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,color:"#fff"}}>✓</div>}
                </div>
                <div style={{flex:1,minWidth:0}}>
                  <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start"}}>
                    <div style={{color:"#fff",fontWeight:800,fontSize:13,lineHeight:1.2}}>{d.name}</div>
                    <div style={{textAlign:"right",flexShrink:0,marginLeft:8}}>
                      <div style={{color:"#F4A012",fontSize:11,fontWeight:700}}>⭐ {d.rating}</div>
                      <div style={{color:"rgba(255,255,255,0.3)",fontSize:9,marginTop:1}}>({d.reviews})</div>
                    </div>
                  </div>
                  <div style={{color:"#00C9A7",fontSize:11,fontWeight:600,marginTop:2}}>{d.spec} · {d.subSpec}</div>
                  <div style={{color:"rgba(255,255,255,0.4)",fontSize:11,marginTop:1}}>{d.qual} · {d.exp} · {d.city}</div>
                  <div style={{color:"rgba(255,255,255,0.35)",fontSize:11,marginTop:1}}>🏥 {d.hosp}</div>
                  <div style={{display:"flex",gap:6,marginTop:7,flexWrap:"wrap",alignItems:"center"}}>
                    {d.online&&<span style={{background:"rgba(0,201,167,0.12)",border:"1px solid rgba(0,201,167,0.3)",borderRadius:6,padding:"2px 7px",color:"#00C9A7",fontSize:10,fontWeight:700}}>📹 Online</span>}
                    {d.offline&&<span style={{background:"rgba(94,53,177,0.12)",border:"1px solid rgba(94,53,177,0.3)",borderRadius:6,padding:"2px 7px",color:"#B39DDB",fontSize:10,fontWeight:700}}>🏥 Clinic</span>}
                    <span style={{color:"rgba(255,255,255,0.3)",fontSize:10}}>Next: {d.nextSlot}</span>
                    <span style={{color:"#00C9A7",fontWeight:800,fontSize:12,marginLeft:"auto"}}>₹{d.fee}</span>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </>
      )}
      {searchTab==="hospitals"&&(
        <>
          {filteredHosps.length===0&&<div style={{textAlign:"center",padding:"30px 0"}}><div style={{fontSize:40,marginBottom:10}}>🔍</div><div style={{color:"rgba(255,255,255,0.4)",fontSize:13}}>No hospitals matched your search</div></div>}
          {filteredHosps.map((h,i)=>(
            <div key={h.id} onClick={()=>setViewHospital(h)} style={{background:"rgba(255,255,255,0.035)",border:"1px solid rgba(255,255,255,0.07)",borderRadius:16,padding:14,cursor:"pointer"}}>
              <div style={{display:"flex",gap:11,alignItems:"flex-start"}}>
                <div style={{width:50,height:50,borderRadius:14,background:"linear-gradient(135deg,#1B5E20,#2E7D32)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:26,flexShrink:0}}>{h.img}</div>
                <div style={{flex:1}}>
                  <div style={{display:"flex",justifyContent:"space-between"}}>
                    <div style={{color:"#fff",fontWeight:800,fontSize:13}}>{h.name}</div>
                    <div style={{color:"#F4A012",fontSize:11,fontWeight:700,flexShrink:0,marginLeft:8}}>⭐ {h.rating}</div>
                  </div>
                  <div style={{color:"rgba(255,255,255,0.4)",fontSize:11,marginTop:2}}>{h.city}, {h.state} · {h.beds} beds</div>
                  <div style={{color:"rgba(255,255,255,0.3)",fontSize:11,marginTop:1}}>{h.type} · {h.accred}</div>
                  <div style={{display:"flex",gap:5,marginTop:7,flexWrap:"wrap"}}>
                    {h.specs.slice(0,3).map(s=><span key={s} style={{background:"rgba(46,125,50,0.12)",border:"1px solid rgba(46,125,50,0.3)",borderRadius:6,padding:"2px 7px",color:"#81C784",fontSize:10}}>{s}</span>)}
                    {h.specs.length>3&&<span style={{color:"rgba(255,255,255,0.3)",fontSize:10,alignSelf:"center"}}>+{h.specs.length-3}</span>}
                  </div>
                </div>
              </div>
              <div style={{display:"flex",justifyContent:"space-between",marginTop:9,paddingTop:9,borderTop:"1px solid rgba(255,255,255,0.05)"}}>
                <div style={{color:"rgba(255,255,255,0.35)",fontSize:10}}>⏰ {h.opd}</div>
                {h.emergency&&<span style={{background:"rgba(255,71,87,0.12)",border:"1px solid rgba(255,71,87,0.3)",borderRadius:6,padding:"2px 7px",color:"#FF4757",fontSize:10,fontWeight:700}}>🚨 24/7 Emergency</span>}
              </div>
            </div>
          ))}
        </>
      )}
    </div>
  );
}

