// ─── SHARED UI COMPONENTS ───────────────────────────────────────────
function MCard({children,style={},onClick}){
  return <div onClick={onClick} style={{background:"rgba(255,255,255,0.03)",border:"1px solid rgba(255,255,255,0.08)",borderRadius:16,padding:14,...style,cursor:onClick?"pointer":"default"}}>{children}</div>;
}
function MBadge({label,color="#00C9A7",icon}){
  return <span style={{display:"inline-flex",alignItems:"center",gap:3,background:`${color}15`,border:`1px solid ${color}35`,borderRadius:6,padding:"3px 9px",color,fontSize:9,fontWeight:800,marginRight:3,marginBottom:3}}>{icon}{label}</span>;
}
function MInp({label,value,onChange,placeholder,type="text",opts,rows,req,sm}){
  const fs={width:"100%",background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:10,color:"rgba(255,255,255,0.92)",fontSize:12,padding:"10px 12px",fontFamily:"Outfit,sans-serif",boxSizing:"border-box"};
  return <div style={{marginBottom:sm?8:13}}>{label&&<div style={{color:"rgba(255,255,255,0.4)",fontSize:10,fontWeight:700,letterSpacing:.4,marginBottom:4,textTransform:"uppercase"}}>{label}{req&&<span style={{color:"#FF4757",marginLeft:3}}>*</span>}</div>}{opts?<select value={value} onChange={e=>onChange(e.target.value)} style={fs}>{opts.map(o=><option key={o} value={o} style={{background:"#0A1628"}}>{o}</option>)}</select>:rows?<textarea value={value} onChange={e=>onChange(e.target.value)} rows={rows} placeholder={placeholder} style={{...fs,resize:"none"}}/>:<input type={type} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder} style={fs}/>}</div>;
}
function MMulti({label,list,sel,onChange,color="#00C9A7"}){
  const t=v=>onChange(sel.includes(v)?sel.filter(x=>x!==v):[...sel,v]);
  return <div style={{marginBottom:13}}>{label&&<div style={{color:"rgba(255,255,255,0.4)",fontSize:10,fontWeight:700,letterSpacing:.4,marginBottom:6,textTransform:"uppercase"}}>{label}</div>}<div style={{display:"flex",flexWrap:"wrap"}}>{list.map(it=>{const a=sel.includes(it);return <span key={it} onClick={()=>t(it)} style={{display:"inline-flex",padding:"5px 10px",borderRadius:50,margin:"2px",border:`1.5px solid ${a?color:"rgba(255,255,255,0.1)"}`,background:a?`${color}18`:"transparent",color:a?color:"rgba(255,255,255,0.3)",fontSize:10,fontWeight:600,cursor:"pointer"}}>{it}</span>;})}</div></div>;
}
function MStep({total,cur,color}){
  return <div style={{display:"flex",alignItems:"center",marginBottom:16}}>{Array.from({length:total},(_,i)=><div key={i} style={{display:"flex",alignItems:"center",flex:1}}><div style={{display:"flex",flexDirection:"column",alignItems:"center",flex:1}}><div style={{width:26,height:26,borderRadius:"50%",background:i<cur?"#00C9A7":i===cur?color:"rgba(255,255,255,0.07)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,color:"#fff",fontWeight:900,border:`2px solid ${i<cur?"#00C9A7":i===cur?color:"rgba(255,255,255,0.1)"}`}}>{i<cur?"✓":i+1}</div></div>{i<total-1&&<div style={{height:2,flex:.6,marginBottom:14,background:i<cur?"#00C9A7":"rgba(255,255,255,0.07)"}}/>}</div>)}</div>;
}
function MHero({title,sub,icon,gradient,stats,children}){
  return <div style={{background:gradient,borderRadius:20,padding:18,marginBottom:14,position:"relative",overflow:"hidden"}}><div style={{position:"absolute",top:-20,right:-20,width:100,height:100,borderRadius:"50%",background:"rgba(255,255,255,0.04)"}}/><div style={{position:"absolute",bottom:-15,left:-15,width:70,height:70,borderRadius:"50%",background:"rgba(255,255,255,0.03)"}}/><div style={{position:"relative"}}><div style={{fontSize:32,marginBottom:5}}>{icon}</div><div style={{color:"rgba(255,255,255,0.5)",fontSize:10,marginBottom:1}}>{sub}</div><div style={{color:"#fff",fontWeight:900,fontSize:17,fontFamily:"Playfair Display,serif",lineHeight:1.2,marginBottom:4}}>{title}</div>{children}<div style={{display:"flex",gap:8,marginTop:10,flexWrap:"wrap"}}>{(stats||[]).map((s,i)=><div key={i} style={{background:"rgba(255,255,255,0.12)",borderRadius:9,padding:"5px 11px",textAlign:"center"}}><div style={{color:"#fff",fontWeight:900,fontSize:14}}>{s.v}</div><div style={{color:"rgba(255,255,255,0.5)",fontSize:8}}>{s.l}</div></div>)}</div></div></div>;
}
function MTabs({tabs,active,onChange,color}){
  return <div style={{display:"flex",gap:3,marginBottom:13,background:"rgba(255,255,255,0.03)",borderRadius:11,padding:4}}>{tabs.map(t=><div key={t.id} onClick={()=>onChange(t.id)} style={{flex:1,padding:"8px 3px",textAlign:"center",borderRadius:8,cursor:"pointer",background:active===t.id?`${color}20`:"transparent",border:active===t.id?`1px solid ${color}40`:"1px solid transparent"}}><div style={{fontSize:14}}>{t.icon}</div><div style={{color:active===t.id?color:"rgba(255,255,255,0.3)",fontSize:8,fontWeight:700,marginTop:1}}>{t.label}</div></div>)}</div>;
}
function MBtn({children,onClick,secondary,style={},disabled}){
  return <button onClick={onClick} disabled={disabled} style={{padding:"10px 16px",background:secondary?"rgba(255,255,255,0.06)":"linear-gradient(135deg,#0066CC,#5E35B1)",border:secondary?"1px solid rgba(255,255,255,0.12)":"none",borderRadius:11,color:"#fff",fontSize:12,fontWeight:700,cursor:disabled?"not-allowed":"pointer",fontFamily:"Outfit,sans-serif",opacity:disabled?.6:1,...style}}>{children}</button>;
}
function BackBtn({onClick}){
  return <button onClick={onClick} style={{background:"rgba(255,255,255,0.07)",border:"none",borderRadius:9,width:32,height:32,cursor:"pointer",color:"#fff",fontSize:14,flexShrink:0}}>←</button>;
}

