function WidgetManagerBtn({roleId,enabled,onChange}){
  const [open,setOpen]=useState(false);
  const all=DEFAULT_WIDGETS[roleId]||DEFAULT_WIDGETS.doctor;
  const toggle=id=>onChange(enabled.includes(id)?enabled.filter(x=>x!==id):[...enabled,id]);
  return(
    <>
      <div onClick={()=>setOpen(true)} style={{display:"flex",alignItems:"center",gap:6,background:"rgba(255,255,255,0.05)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:9,padding:"6px 12px",cursor:"pointer",marginBottom:10}}>
        <span style={{fontSize:12}}>🧩</span>
        <span style={{color:"rgba(255,255,255,0.5)",fontSize:10,fontWeight:700}}>Customize Widgets</span>
        <span style={{marginLeft:"auto",color:"rgba(255,255,255,0.3)",fontSize:10}}>{enabled.length}/{all.length} active ›</span>
      </div>
      {open&&<div style={{position:"fixed",inset:0,background:"rgba(0,0,0,0.7)",zIndex:900,display:"flex",alignItems:"flex-end"}} onClick={()=>setOpen(false)}>
        <div onClick={e=>e.stopPropagation()} style={{width:"100%",maxWidth:390,background:"linear-gradient(180deg,#0C1E40,#070E1A)",borderRadius:"20px 20px 0 0",padding:"18px 14px 28px",border:"1px solid rgba(255,255,255,0.08)",borderBottom:"none",maxHeight:"80vh",overflowY:"auto"}}>
          <div style={{width:40,height:4,background:"rgba(255,255,255,0.2)",borderRadius:2,margin:"0 auto 14px"}}/>
          <div style={{color:"#fff",fontWeight:800,fontSize:14,marginBottom:3}}>🧩 Dashboard Widgets</div>
          <div style={{color:"rgba(255,255,255,0.4)",fontSize:10,marginBottom:14}}>Toggle widgets to customize your dashboard</div>
          {all.map(id=>{const m=WIDGET_META[id];const on=enabled.includes(id);return m?(
            <div key={id} onClick={()=>toggle(id)} style={{display:"flex",alignItems:"center",gap:11,padding:"11px 12px",background:on?"rgba(0,201,167,0.06)":"rgba(255,255,255,0.02)",border:`1.5px solid ${on?"rgba(0,201,167,0.25)":"rgba(255,255,255,0.07)"}`,borderRadius:12,marginBottom:7,cursor:"pointer"}}>
              <span style={{fontSize:18,flexShrink:0}}>{m.icon}</span>
              <div style={{flex:1}}><div style={{color:"#fff",fontWeight:700,fontSize:12}}>{m.label}</div><div style={{color:"rgba(255,255,255,0.35)",fontSize:10,marginTop:1}}>{m.desc}</div></div>
              <div style={{width:36,height:20,borderRadius:10,background:on?"#00C9A7":"rgba(255,255,255,0.1)",position:"relative",flexShrink:0,transition:"background .2s"}}>
                <div style={{position:"absolute",top:3,left:on?18:3,width:14,height:14,borderRadius:"50%",background:"#fff",transition:"left .2s"}}/>
              </div>
            </div>
          ):null;})}
          <EBtn onClick={()=>setOpen(false)} style={{width:"100%",marginTop:10}}>✅ Done</EBtn>
        </div>
      </div>}
    </>
  );
}

